# Script: 03_meth-pheno_ass.R
# Purposes: Methylation–Phenotype Association Analysis
# Part 1. Prepares methylation and phenotype data.
# Part 2: Evaluates associations using beta regression.
# Part 3: Performs linear-model-based association analysis.

# Inputs:
# 1. Working directory with methylation_coverage data generated by nf-core/methylseq.
# 2. Sample description Excel file.
# 3. Worksheet name specifying the phenotype of interest and sex (e.g Female_ACQ)

# Usage:
#   Rscript 03_meth-pheno_ass.R \
#       <working_directory> \
#       <sample_sheet2.xlsx> \
#       <worksheet_name> \

## Output:
##Beta regression association results (.csv/.xlsx)
##Limma association results (.csv/.xlsx)
##Generated plots and figures

## To ensure that R script accepts command-line arguments using commandArgs().
args <- commandArgs(trailingOnly = TRUE)
direc <- args[1] # 1st argument (working directory)
target <- args[2]
target_sheet <- args[3]

## Uncomment the lines below only for interactive testing in RStudio
# direc <- "C:/Users/..."
# target <- "C:/Users/.../sample_sheet2.xlsx"
# target_sheet <- "Female_REV" or "Male_ACQ"
##"Female_REV"/"Male_ACQ"/"Male_REV"
##** ACQ: Acquisition Learning; REV: Reversal Learning **##

