} else {
  formula_strA1 <- paste0("beta ~ ",behav," + batch")
  formulaA1 <- as.formula(formula_strA1)
  formulaA1
}

################################################################################
process_row <- function(i, bv_filtered_df, pheno, formulaA1) {
  df <- data.frame(beta = as.numeric(bv_filtered_df[i, ]), pheno)
  if (length(unique(df$beta)) < 3) return(NULL)
  
  tryCatch({
    fit <- betareg(formulaA1, data = df)
    coefs <- summary(fit)$coefficients$mean
    if (!behav %in% rownames(coefs)) stop(paste(behav, "dropped"))
    out <- coefs[behav, ]
    data.frame(CpG = rownames(bv_filtered_df)[i],
               Estimate = out["Estimate"],
               StdErr   = out["Std. Error"],
               zval     = out["z value"],
               pval     = out["Pr(>|z|)"],
               Model    = "Full")
  })
}

library(future)
library(future.apply)

# Detect number of CPUs assigned by SLURM
slurm_cpus <- as.numeric(Sys.getenv("SLURM_CPUS_PER_TASK", "1"))

# If not defined, default to a safe number
