  future.availableCores.methods = c("system", "env"),
  mc.cores = slurm_cpus,
  future.globals.maxSize = 2 * 1024^3
)
plan(multisession, workers = slurm_cpus)

#### run the function
results_betareg_sv1 <- future_lapply(
  1:nrow(bv_filtered_df),
  function(i) process_row(i, bv_filtered_df, pheno, formulaA1)
)
results_betareg_sv1 <- do.call(rbind, results_betareg_sv1)

