# LIMMA Section uses M-Values
library(limma)
M_filtered_df <- M_filtered

if(use_batch) {
  formul<- as.formula(paste0("~ ", behav, " + batch + ", paste0(sv_names, collapse = "+")))
  formul
} else {
  formul<- as.formula(paste0("~ ", behav, " + batch"))
  formul
}

#===========================#
design <- model.matrix(formul, data = pheno)
limma_fit <- lmFit(M_filtered_df, design)

## empirical Bayes with robust=TRUE (more robust to outliers / variance heterogeneity)
limma_fit2 <- eBayes(limma_fit, robust = TRUE)

## diagnostic plot of residuals vs average expression
limma::plotSA(limma_fit2)    # shows mean-variance trend and effectiveness of shrinkage

## Top table
results_limma <- topTable(limma_fit2, coef = behav, number=Inf, sort.by="p")
write.csv(results_limma, file = paste0(target_sheet, "_Cor_all_limma_sv.csv"))
#write.xlsx(results_limma, paste0(target_sheet,"_SVN_limma.xlsx"),rowNames=T)

